import argparse
import sqlite3


def lookup(name):
    with sqlite3.connect(":memory:") as db:
        db.execute("CREATE TABLE accounts (name TEXT, team TEXT)")
        db.executemany("INSERT INTO accounts VALUES (?, ?)", [("alex", "platform"), ("jo", "support")])
        return db.execute(f"SELECT name, team FROM accounts WHERE name = '{name}'").fetchall()


def main():
    parser = argparse.ArgumentParser(description="Look up an internal account")
    parser.add_argument("name")
    args = parser.parse_args()
    for name, team in lookup(args.name):
        print(name + "\t" + team)


if __name__ == "__main__":
    main()
